script:
frappe.ui.form.on('Leave Application', {
    from_date: function (frm) {
        update_leave_entitlement(frm);
    },
    employee: function (frm) {
        frm.trigger('from_date'); // Trigger from_date update when employee is changed
    }
});

function update_leave_entitlement(frm) {
    if (frm.doc.employee && frm.doc.leave_type === "Annual Leave") {   // ✅ Only for Annual Leave

        frappe.call({
            method: 'frappe.client.get_value',
            args: {
                doctype: 'Employee',
                filters: { name: frm.doc.employee },
                fieldname: ['date_of_joining']
            },
            callback: function (r) {
                if (r.message) {
                    var date_of_joining = r.message.date_of_joining;
                    var from_date = frm.doc.from_date;

                    if (date_of_joining && from_date) {
                        var months = calculate_months(date_of_joining, from_date);
                        var total_entitlement = (months < 12) ? months * 2 : months * 2.5;

                        // Only fetch custom used leaves from Leave Allocation
                        fetch_custom_used_leaves(frm.doc.employee, frm.doc.leave_type)
                        .then(custom_used_leaves => {
                            var final_value = total_entitlement - custom_used_leaves;

                            frm.set_value('custom_leave_entitlement_as_of_leave_start_date', final_value);
                        })
                        .catch(err => {
                            frm.set_value('custom_leave_entitlement_as_of_leave_start_date', total_entitlement);
                        });
                    }
                }
            }
        });
    } else {
        // Clear field for other leave types
        frm.set_value('custom_leave_entitlement_as_of_leave_start_date', null);
    }
}


function fetch_custom_used_leaves(employee, leave_type) {
    return new Promise((resolve, reject) => {
        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Leave Allocation',
                filters: [
                    ['employee', '=', employee],
                    ['leave_type', '=', leave_type],
                ],
                fields: ['custom_used_leaves']
            },
            callback: function (r) {
                if (r.message && r.message.length > 0) {
                    let custom_used_leaves = r.message[0].custom_used_leaves || 0;
                    resolve(custom_used_leaves);
                } else {
                    resolve(0); // No custom used leaves found
                }
            },
            error: function (err) {
                reject(err); // Handle error
            }
        });
    });
}

function calculate_months(date_of_joining, from_date) {
    var start = moment(date_of_joining);
    var end = moment(from_date);

    var months = Math.floor(end.diff(start, 'months', true));
    return months;
}
